{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2186-03-08 17:00:00",
      "speaker": "Doctor",
      "text": "Hello, I’m Dr. Lee. You’re here today for your scheduled IVIG infusion, correct?"
    },
    {
      "turn_number": 2,
      "time": "2186-03-08 17:02:00",
      "speaker": "Patient",
      "text": "Yes, that’s right. This is my fifth one. I’ve been getting them every month, but now we’re switching to half-doses every two weeks."
    },
    {
      "turn_number": 3,
      "time": "2186-03-08 17:04:00",
      "speaker": "Doctor",
      "text": "That’s correct. We’re adjusting the schedule to see if it reduces side effects. I see you’ve had some reactions before—chest tightness, shortness of breath?"
    },
    {
      "turn_number": 4,
      "time": "2186-03-08 17:05:30",
      "speaker": "Patient",
      "text": "Yes, after the last one I had chest tightness and a headache. My blood pressure spiked too. But it all passed in a day."
    },
    {
      "turn_number": 5,
      "time": "2186-03-08 17:07:00",
      "speaker": "Doctor",
      "text": "We’ll monitor you closely. We’ll also give you fluids tonight to help with your orthostatic hypotension."
    },
    {
      "turn_number": 6,
      "time": "2186-03-08 17:08:30",
      "speaker": "Patient",
      "text": "That’s good. I’ve been getting those NS boluses at home too, three times a week."
    },
    {
      "turn_number": 7,
      "time": "2186-03-08 17:10:00",
      "speaker": "Doctor",
      "text": "Yes, and we’ll continue that. How are you feeling now?"
    },
    {
      "turn_number": 8,
      "time": "2186-03-08 17:11:00",
      "speaker": "Patient",
      "text": "A little warm, actually. I’ve had a low-grade fever since this afternoon."
    },
    {
      "turn_number": 9,
      "time": "2186-03-08 17:12:30",
      "speaker": "Doctor",
      "text": "Your temperature is 100.8, which is slightly elevated. We’ll check a chest X-ray and get blood and urine cultures just to be safe."
    },
    {
      "turn_number": 10,
      "time": "2186-03-08 17:14:00",
      "speaker": "Patient",
      "text": "Is that normal with IVIG? I don’t want this to delay the infusion."
    },
    {
      "turn_number": 11,
      "time": "2186-03-08 17:15:30",
      "speaker": "Doctor",
      "text": "We don’t expect fever from IVIG, so we want to rule out infection. But this won’t delay your infusion. We’ll proceed as planned."
    },
    {
      "turn_number": 12,
      "time": "2186-03-08 17:17:00",
      "speaker": "Patient",
      "text": "Okay, that’s a relief. My heart history makes me nervous about any chest symptoms."
    },
    {
      "turn_number": 13,
      "time": "2186-03-08 17:18:30",
      "speaker": "Doctor",
      "text": "Completely understandable. You have a strong cardiac history—multiple stents, angina. We’ll keep an eye on your heart throughout."
    },
    {
      "turn_number": 14,
      "time": "2186-03-08 17:20:00",
      "speaker": "Patient",
      "text": "I’m on aspirin, Plavix, metoprolol, valsartan… all the usual meds."
    },
    {
      "turn_number": 15,
      "time": "2186-03-08 17:21:30",
      "speaker": "Doctor",
      "text": "Yes, and you’ll continue all of those. No changes there."
    },
    {
      "turn_number": 16,
      "time": "2186-03-08 23:05:00",
      "speaker": "Doctor",
      "text": "Your chest X-ray came back clear—no pneumonia or fluid. That’s reassuring."
    },
    {
      "turn_number": 17,
      "time": "2186-03-08 23:07:00",
      "speaker": "Patient",
      "text": "Good. And the cultures?"
    },
    {
      "turn_number": 18,
      "time": "2186-03-08 23:08:30",
      "speaker": "Doctor",
      "text": "Still pending, but the first blood culture showed no growth. Urine had low organisms, not enough to call an infection."
    },
    {
      "turn_number": 19,
      "time": "2186-03-08 23:10:00",
      "speaker": "Patient",
      "text": "So probably not an infection?"
    },
    {
      "turn_number": 20,
      "time": "2186-03-08 23:11:30",
      "speaker": "Doctor",
      "text": "Unlikely. The fever may just be a mild reaction. We gave you Tylenol, and you’re now afebrile."
    },
    {
      "turn_number": 21,
      "time": "2186-03-08 23:13:00",
      "speaker": "Patient",
      "text": "That makes sense. I’ve had fevers before with autonomic dysfunction."
    },
    {
      "turn_number": 22,
      "time": "2186-03-08 23:14:30",
      "speaker": "Doctor",
      "text": "Exactly. We’ve given you 2 liters of saline, which should help stabilize you for tomorrow’s infusion."
    },
    {
      "turn_number": 23,
      "time": "2186-03-09 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. How are you feeling?"
    },
    {
      "turn_number": 24,
      "time": "2186-03-09 08:02:00",
      "speaker": "Patient",
      "text": "Much better. No fever, no dizziness. Ready for the infusion."
    },
    {
      "turn_number": 25,
      "time": "2186-03-09 08:04:00",
      "speaker": "Doctor",
      "text": "We’ll pre-medicate you with Benadryl and Tylenol about 30 minutes before to reduce reaction risk."
    },
    {
      "turn_number": 26,
      "time": "2186-03-09 08:05:30",
      "speaker": "Patient",
      "text": "Same as last time?"
    },
    {
      "turn_number": 27,
      "time": "2186-03-09 08:07:00",
      "speaker": "Doctor",
      "text": "Yes. You’ll get 15 grams of IVIG—half your previous dose—but more frequently."
    },
    {
      "turn_number": 28,
      "time": "2186-03-09 12:05:00",
      "speaker": "Doctor",
      "text": "You’re about halfway through the infusion. How are you doing?"
    },
    {
      "turn_number": 29,
      "time": "2186-03-09 12:07:00",
      "speaker": "Patient",
      "text": "I feel a little short of breath. Not bad, but it’s there."
    },
    {
      "turn_number": 30,
      "time": "2186-03-09 12:08:30",
      "speaker": "Doctor",
      "text": "We’ll put you on 2 liters of oxygen by nasal cannula. You’re not hypoxic, but this will help."
    },
    {
      "turn_number": 31,
      "time": "2186-03-09 12:10:00",
      "speaker": "Patient",
      "text": "Is this normal?"
    },
    {
      "turn_number": 32,
      "time": "2186-03-09 12:11:30",
      "speaker": "Doctor",
      "text": "Mild shortness of breath has happened before with your infusions. It’s not dangerous and should resolve."
    },
    {
      "turn_number": 33,
      "time": "2186-03-09 12:13:00",
      "speaker": "Patient",
      "text": "Any chest tightness?"
    },
    {
      "turn_number": 34,
      "time": "2186-03-09 12:14:30",
      "speaker": "Doctor",
      "text": "You mentioned mild discomfort earlier, but your blood pressure and heart rate are stable. No signs of heart issues."
    },
    {
      "turn_number": 35,
      "time": "2186-03-09 15:00:00",
      "speaker": "Doctor",
      "text": "Infusion is complete. You’re doing well. The shortness of breath has improved with oxygen."
    },
    {
      "turn_number": 36,
      "time": "2186-03-09 15:02:00",
      "speaker": "Patient",
      "text": "I feel okay now. A bit tired, but no chest pain."
    },
    {
      "turn_number": 37,
      "time": "2186-03-10 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’ve had a quiet night, afebrile, no symptoms. We’re ready to discharge you."
    },
    {
      "turn_number": 38,
      "time": "2186-03-10 09:02:00",
      "speaker": "Patient",
      "text": "Great. So the reaction was mild this time?"
    },
    {
      "turn_number": 39,
      "time": "2186-03-10 09:04:00",
      "speaker": "Doctor",
      "text": "Yes, much milder than before. The adjusted dose may be helping. Continue your regular meds and IV fluids at home."
    },
    {
      "turn_number": 40,
      "time": "2186-03-10 09:06:00",
      "speaker": "Patient",
      "text": "And same follow-up with immunology?"
    },
    {
      "turn_number": 41,
      "time": "2186-03-10 09:07:30",
      "speaker": "Doctor",
      "text": "Yes, and we’ll monitor how you tolerate this new schedule. Call if you develop fever, chest pain, or trouble breathing."
    },
    {
      "turn_number": 42,
      "time": "2186-03-10 09:09:00",
      "speaker": "Patient",
      "text": "Will do. Thanks for watching me so closely."
    },
    {
      "turn_number": 43,
      "time": "2186-03-10 09:10:30",
      "speaker": "Doctor",
      "text": "Of course. You’re stable and in good condition. We’ll get your discharge papers ready."
    },
    {
      "turn_number": 44,
      "time": "2186-03-10 09:12:00",
      "speaker": "Patient",
      "text": "I’m glad everything went smoothly."
    },
    {
      "turn_number": 45,
      "time": "2186-03-10 09:13:30",
      "speaker": "Doctor",
      "text": "So are we. You responded well to the IVIG, and your strength seems to be improving overall."
    },
    {
      "turn_number": 46,
      "time": "2186-03-10 09:15:00",
      "speaker": "Patient",
      "text": "Yes, I do feel stronger than I did a few months ago."
    },
    {
      "turn_number": 47,
      "time": "2186-03-10 09:16:30",
      "speaker": "Doctor",
      "text": "That’s the goal. Keep up with your appointments and fluid boluses."
    },
    {
      "turn_number": 48,
      "time": "2186-03-10 09:18:00",
      "speaker": "Patient",
      "text": "I will. And I’ll see dermatology about that leg lesion soon."
    },
    {
      "turn_number": 49,
      "time": "2186-03-10 09:19:30",
      "speaker": "Doctor",
      "text": "Good idea, especially with your history of skin cancer."
    },
    {
      "turn_number": 50,
      "time": "2186-03-10 09:21:00",
      "speaker": "Patient",
      "text": "Thanks again, Doctor."
    },
    {
      "turn_number": 51,
      "time": "2186-03-10 09:22:30",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and we’ll see you for your next infusion."
    }
  ],
  "summary": {
    "admission_start": "2186-03-08 16:56:00",
    "admission_end": "2186-03-10 13:00:00",
    "summary_paragraph": "A male patient with a history of hypogammaglobulinemia, mitochondrial disease, and coronary artery disease was admitted for observation during a scheduled IVIG infusion. He had a low-grade fever on admission, which resolved with Tylenol; chest X-ray and cultures showed no infection. He received 2 liters of saline before the infusion and was pre-medicated with Benadryl and Tylenol. During the IVIG infusion, he developed mild shortness of breath, improved with 2 liters of oxygen, but remained stable without hypoxia or cardiac symptoms. He tolerated the half-dose regimen well, with fewer side effects than in prior infusions. No medication changes were made. He was discharged home in stable condition with instructions to continue outpatient IVIG, fluid boluses, and follow-up with specialists.",
    "problems": [
      "Hypogammaglobulinemia, unspecified",
      "Disorders of mitochondrial metabolism",
      "Fever, unspecified",
      "Shortness of breath",
      "Other chest pain",
      "Orthostatic hypotension",
      "Coronary atherosclerosis of native coronary artery",
      "Other and unspecified angina pectoris",
      "Percutaneous transluminal coronary angioplasty status",
      "Esophageal reflux",
      "Chronic kidney disease, Stage III (moderate)",
      "Symptomatic inflammatory myopathy in diseases classified elsewhere"
    ]
  }
}
